#include <iomanip>
#include <iostream>
#include <limits>
#include <optional>
#include <vector>

std::vector<double> nettoyer_montants(const std::vector<std::optional<double>>& montants) {
    double somme = 0.0;
    std::size_t n = 0;
    for (const auto& m : montants)
        if (m) { somme += *m; ++n; }  // mean() ignore les NaN
    const double moyenne = n ? somme / static_cast<double>(n)
                             : std::numeric_limits<double>::quiet_NaN();  // pandas : mean() d'une serie vide = NaN
    std::vector<double> resultat;
    resultat.reserve(montants.size());
    for (const auto& m : montants)
        resultat.push_back(m.value_or(moyenne));
    return resultat;
}

int main() {
    const std::vector<std::optional<double>> s = {100.0, std::nullopt, 250.5, std::nullopt, 49.5};
    const auto propre = nettoyer_montants(s);
    std::cout << std::fixed << std::setprecision(2) << "valeurs:";
    for (double v : propre) std::cout << ' ' << v;
    std::cout << '\n';
    std::size_t non_nuls = 0;
    for (const auto& m : s) if (m) ++non_nuls;
    std::cout << "lignes sans NaN: " << non_nuls << '\n';
}

