#include <vector>

std::string strip_lower(const std::string& s) {
    const auto debut = s.find_first_not_of(" \t\n\r\f\v");
    if (debut == std::string::npos) return "";
    const auto fin = s.find_last_not_of(" \t\n\r\f\v");
    std::string r = s.substr(debut, fin - debut + 1);
    std::transform(r.begin(), r.end(), r.begin(),
                   [](unsigned char c) { return static_cast<char>(std::tolower(c)); });
    return r;
}

std::vector<std::string> normaliser_clients(const std::vector<std::string>& noms) {
    std::unordered_set<std::string> vus;
    std::vector<std::string> resultat;
    for (const auto& nom : noms) {
        std::string propre = strip_lower(nom);
        if (!propre.empty() && vus.insert(propre).second)  // insert().second == true si nouvel element
            resultat.push_back(propre);
    }
    return resultat;
}

int main() {
    const auto r = normaliser_clients({"  Dupont ", "dupont", "MARTIN", "", "Martin  ", "Durand"});
    for (std::size_t i = 0; i < r.size(); ++i)
        std::cout << (i ? "|" : "") << r[i];
    std::cout << '\n';
}

