#include <cstddef>
#include <iomanip>
#include <iostream>
#include <stdexcept>
#include <vector>

struct ModeleLineaire {
    double pente = 0.0;
    double ordonnee = 0.0;

    double predict(double x) const { return pente * x + ordonnee; }
};

// Moindres carres ordinaires, solution fermee (equivalent de LinearRegression pour 1 variable)
ModeleLineaire fit(const std::vector<double>& x, const std::vector<double>& y) {
    if (x.size() != y.size() || x.size() < 2)
        throw std::invalid_argument("x et y doivent avoir la meme taille (>= 2)");
    const double n = static_cast<double>(x.size());
    double mx = 0.0, my = 0.0;
    for (std::size_t i = 0; i < x.size(); ++i) { mx += x[i]; my += y[i]; }
    mx /= n;
    my /= n;
    double sxy = 0.0, sxx = 0.0;
    for (std::size_t i = 0; i < x.size(); ++i) {
        sxy += (x[i] - mx) * (y[i] - my);
        sxx += (x[i] - mx) * (x[i] - mx);
    }
    ModeleLineaire m;
    m.pente = sxy / sxx;
    m.ordonnee = my - m.pente * mx;
    return m;
}

int main() {
    const std::vector<double> surface = {30.0, 45.0, 60.0, 80.0, 100.0};
    const std::vector<double> prix = {150.0, 210.0, 270.0, 345.0, 420.0};
    const ModeleLineaire modele = fit(surface, prix);
    std::cout << std::fixed << std::setprecision(4)
              << "pente=" << modele.pente << " ordonnee=" << modele.ordonnee << '\n'
              << std::setprecision(2) << "prediction 70m2=" << modele.predict(70.0) << '\n';
}

#include <cmath>
#include <cstddef>
#include <iomanip>
#include <iostream>
#include <vector>

using Matrice = std::vector<std::vector<double>>;

struct Scaler {
    std::vector<double> moyenne, ecart_type;

    void fit(const Matrice& X) {
        const std::size_t n = X.size(), p = X.at(0).size();
        moyenne.assign(p, 0.0);
        ecart_type.assign(p, 0.0);
        for (const auto& ligne : X)
            for (std::size_t j = 0; j < p; ++j) moyenne[j] += ligne[j];
        for (auto& m : moyenne) m /= static_cast<double>(n);
        for (const auto& ligne : X)
            for (std::size_t j = 0; j < p; ++j) ecart_type[j] += (ligne[j] - moyenne[j]) * (ligne[j] - moyenne[j]);
        for (auto& e : ecart_type) {
            e = std::sqrt(e / static_cast<double>(n));  // ecart-type de population (ddof=0), comme sklearn
            if (e == 0.0) e = 1.0;                       // sklearn : colonne constante -> on ne divise pas
        }
    }

    Matrice transform(const Matrice& X) const {
        Matrice r = X;
        for (auto& ligne : r)
            for (std::size_t j = 0; j < ligne.size(); ++j) ligne[j] = (ligne[j] - moyenne[j]) / ecart_type[j];
        return r;
    }

    Matrice fit_transform(const Matrice& X) { fit(X); return transform(X); }
};

int main() {
    const Matrice X = {{1.0, 200.0}, {2.0, 300.0}, {3.0, 400.0}, {4.0, 1000.0}};
    Scaler scaler;
    std::cout << std::fixed << std::setprecision(4);
    for (const auto& ligne : scaler.fit_transform(X)) {
        for (std::size_t j = 0; j < ligne.size(); ++j) std::cout << (j ? " " : "") << ligne[j];
        std::cout << '\n';
    }
}

