void bar_chart_svg(const std::string& chemin, const std::string& titre,
                   const std::vector<std::string>& etiquettes, const std::vector<double>& valeurs) {
    if (valeurs.empty() || valeurs.size() != etiquettes.size())
        throw std::invalid_argument("etiquettes et valeurs incoherentes");
    const double largeur = 400, hauteur = 300, marge = 40;
    const double max_v = *std::max_element(valeurs.begin(), valeurs.end());
    const double pas = (largeur - 2 * marge) / static_cast<double>(valeurs.size());

    std::ofstream f(chemin);
    if (!f) throw std::runtime_error("impossible d'ecrire " + chemin);
    f << "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"" << largeur << "\" height=\"" << hauteur << "\">\n"
      << "<text x=\"" << largeur / 2 << "\" y=\"20\" text-anchor=\"middle\">" << titre << "</text>\n";
    for (std::size_t i = 0; i < valeurs.size(); ++i) {
        const double h = valeurs[i] / max_v * (hauteur - 2 * marge);
        const double x = marge + static_cast<double>(i) * pas + pas * 0.1;
        f << "<rect x=\"" << x << "\" y=\"" << hauteur - marge - h << "\" width=\"" << pas * 0.8
          << "\" height=\"" << h << "\" fill=\"steelblue\"/>\n"
          << "<text x=\"" << x + pas * 0.4 << "\" y=\"" << hauteur - marge + 15
          << "\" text-anchor=\"middle\">" << etiquettes[i] << "</text>\n";
    }
    f << "</svg>\n";
}

int main() {
    const std::vector<std::string> regions = {"Nord", "Sud", "Est"};
    const std::vector<double> montants = {150.0, 100.0, 45.25};
    bar_chart_svg("ca_regions.svg", "CA par region", regions, montants);
    std::cout << "graphique: " << regions.size() << " barres, max=" << std::fixed << std::setprecision(2)
              << *std::max_element(montants.begin(), montants.end()) << '\n';
}

