std::vector<std::string> split(const std::string& ligne, char sep) {
    std::vector<std::string> champs;
    std::stringstream ss(ligne);
    std::string champ;
    while (std::getline(ss, champ, sep)) champs.push_back(champ);
    return champs;
}

std::vector<std::pair<std::string, double>> total_par_produit(const std::string& chemin) {
    std::ifstream f(chemin);
    if (!f) throw std::runtime_error("fichier introuvable : " + chemin);

    std::string ligne;
    std::getline(f, ligne);
    if (!ligne.empty() && ligne.back() == '\r') ligne.pop_back();
    std::unordered_map<std::string, std::size_t> col;  // nom de colonne -> index (comme DictReader)
    const auto entete = split(ligne, ',');
    for (std::size_t i = 0; i < entete.size(); ++i) col[entete[i]] = i;

    std::vector<std::string> ordre;                    // un dict Python garde l'ordre d'insertion
    std::unordered_map<std::string, double> totaux;
    while (std::getline(f, ligne)) {
        if (!ligne.empty() && ligne.back() == '\r') ligne.pop_back();  // fichiers Windows (\r\n)
        if (ligne.empty()) continue;
        const auto c = split(ligne, ',');
        const std::string& produit = c.at(col.at("produit"));
        if (totaux.find(produit) == totaux.end()) ordre.push_back(produit);
        totaux[produit] += std::stod(c.at(col.at("quantite"))) * std::stod(c.at(col.at("prix")));
    }
    std::vector<std::pair<std::string, double>> resultat;
    for (const auto& p : ordre) resultat.emplace_back(p, totaux[p]);
    return resultat;
}

int main() {
    {
        std::ofstream f("ventes.csv");
        f << "produit,quantite,prix\nstylo,10,1.5\ncahier,3,2.25\nstylo,4,1.5\n";
    }  // fin de portee = fermeture du fichier (equivalent du with)
    std::cout << std::fixed << std::setprecision(2);
    for (const auto& [produit, total] : total_par_produit("ventes.csv"))
        std::cout << produit << ": " << total << '\n';
}

