#include <fstream>
#include <iostream>
#include <stdexcept>
#include <string>

int filtrer_erreurs(const std::string& entree, const std::string& sortie) {
    std::ifstream f_in(entree);
    if (!f_in) throw std::runtime_error("impossible de lire " + entree);
    std::ofstream f_out(sortie);
    if (!f_out) throw std::runtime_error("impossible d'ecrire " + sortie);
    int n = 0;
    std::string ligne;
    while (std::getline(f_in, ligne)) {
        if (ligne.rfind("ERROR", 0) == 0) {  // startswith (C++20 : ligne.starts_with("ERROR"))
            f_out << ligne << '\n';           // getline retire le '\n', on le remet
            ++n;
        }
    }
    return n;
}

int main(int argc, char* argv[]) {
    const std::string chemin = argc > 1 ? argv[1] : "app.log";  // argv[0] = nom du programme, comme en Python
    {
        std::ofstream f(chemin);
        f << "INFO demarrage\nERROR disque plein\nWARN lent\nERROR timeout\n";
    }
    try {
        const int n = filtrer_erreurs(chemin, "erreurs.log");
        std::cout << n << " lignes d'erreur copiees\n";
    } catch (const std::exception& e) {
        std::cerr << "erreur: " << e.what() << '\n';
        return 1;
    }
    return 0;
}

