#include <algorithm>
#include <cmath>
#include <iomanip>
#include <iostream>
#include <numeric>
#include <vector>

double moyenne(const std::vector<double>& v) {
    return std::accumulate(v.begin(), v.end(), 0.0) / static_cast<double>(v.size());  // 0.0 et non 0 !
}

double ecart_type(const std::vector<double>& v) {  // ddof=0 comme numpy
    const double m = moyenne(v);
    const double sc = std::accumulate(v.begin(), v.end(), 0.0,
                                      [m](double acc, double x) { return acc + (x - m) * (x - m); });
    return std::sqrt(sc / static_cast<double>(v.size()));
}

int main() {
    const std::vector<double> notes = {12.0, 15.5, 9.0, 18.0, 14.5};
    const std::vector<double> poids = {1.0, 2.0, 1.0, 3.0, 1.0};
    const double pondere = std::inner_product(notes.begin(), notes.end(), poids.begin(), 0.0)
                           / std::accumulate(poids.begin(), poids.end(), 0.0);
    const auto au_dessus = std::count_if(notes.begin(), notes.end(), [](double x) { return x > 14; });
    std::cout << std::fixed << std::setprecision(4)
              << "moyenne=" << moyenne(notes) << '\n'
              << "ecart-type=" << ecart_type(notes) << '\n'
              << "moyenne ponderee=" << pondere << '\n'
              << "au-dessus de 14: " << au_dessus << '\n';
}

