#include <cstdint>
#include <iostream>

// Python : // arrondit vers -inf et % a le signe du diviseur. C++ : / et % tronquent vers 0.
int64_t floor_div(int64_t a, int64_t b) {
    int64_t q = a / b;
    if ((a % b != 0) && ((a < 0) != (b < 0))) --q;
    return q;
}

int64_t floor_mod(int64_t a, int64_t b) {
    int64_t r = a % b;
    if (r != 0 && ((r < 0) != (b < 0))) r += b;
    return r;
}

int64_t puissance(int64_t base, unsigned exposant) {  // std::pow travaille en double : imprecis au-dela de 2^53
    int64_t r = 1;
    while (exposant--) r *= base;
    return r;
}

int64_t decaler_jour(int64_t jour, int64_t decalage) { return floor_mod(jour + decalage, 7); }
int64_t tranches(int64_t montant, int64_t taille) { return floor_div(montant, taille); }

int main() {
    std::cout << decaler_jour(1, -3) << ' ' << tranches(-7, 2) << ' ' << tranches(7, 2) << ' '
              << puissance(3, 13) << ' ' << static_cast<double>(7) / 2 << '\n';
}

