#include <algorithm>
#include <cmath>
#include <iostream>
#include <numeric>
#include <stdexcept>
#include <vector>

double moyenne(const std::vector<double>& valeurs) {
    if (valeurs.empty()) throw std::domain_error("liste vide");  // en C++, 0.0/0 donne nan sans erreur
    return std::accumulate(valeurs.begin(), valeurs.end(), 0.0) / static_cast<double>(valeurs.size());
}

bool approx(double a, double b, double rel = 1e-6, double abs_tol = 1e-12) {  // = pytest.approx
    return std::fabs(a - b) <= std::max(rel * std::fabs(b), abs_tol);
}

struct Cas {
    std::vector<double> valeurs;
    double attendu;
};

int main() {
    int echecs = 0;
    const std::vector<Cas> cas = {{{1.0, 2.0, 3.0}, 2.0}, {{0.1, 0.2}, 0.15}};  // = parametrize
    for (const auto& c : cas)
        if (!approx(moyenne(c.valeurs), c.attendu)) { ++echecs; std::cerr << "test_moyenne echoue\n"; }

    bool leve = false;  // = pytest.raises
    try { moyenne({}); } catch (const std::domain_error&) { leve = true; }
    if (!leve) { ++echecs; std::cerr << "test_liste_vide echoue\n"; }

    std::cout << (echecs ? "ECHEC" : "OK") << '\n';
    return echecs ? 1 : 0;
}

