#include <cstddef>
#include <cstdint>
#include <iostream>
#include <optional>
#include <stdexcept>
#include <string>
#include <vector>

std::optional<int64_t> parse_int(const std::string& texte) {
    const auto debut = texte.find_first_not_of(" \t\n\r");
    if (debut == std::string::npos) return std::nullopt;
    const auto fin = texte.find_last_not_of(" \t\n\r");
    const std::string s = texte.substr(debut, fin - debut + 1);
    try {
        std::size_t pos = 0;
        const long long v = std::stoll(s, &pos);
        if (pos != s.size()) return std::nullopt;  // stoll("12abc") renvoie 12 sans erreur !
        return static_cast<int64_t>(v);
    } catch (const std::invalid_argument&) {
        return std::nullopt;
    } catch (const std::out_of_range&) {           // Python accepte les grands entiers, pas int64_t
        return std::nullopt;
    }
}

int main() {
    for (const std::string t : {"42", " -7 ", "12abc", "", "3.5", "+8"}) {
        const auto v = parse_int(t);
        std::cout << '[' << t << "] -> ";
        if (v) std::cout << *v; else std::cout << "None";
        std::cout << '\n';
    }
}

