#include <algorithm>
#include <iomanip>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

struct Employe {
    std::string nom;
    double salaire = 0.0;
    std::vector<std::string> competences{};  // default_factory=list : chaque instance a sa propre liste

    std::string resume() const {
        std::ostringstream os;
        os << nom << " (" << std::fixed << std::setprecision(0) << salaire << " EUR) : ";
        if (competences.empty()) {
            os << "aucune";
        } else {
            for (std::size_t i = 0; i < competences.size(); ++i) os << (i ? ", " : "") << competences[i];
        }
        return os.str();
    }
};

int main() {
    std::vector<Employe> equipe = {{"Alice", 4200.0, {"python", "sql"}}, {"Bob", 3950.0}};
    std::stable_sort(equipe.begin(), equipe.end(),
                     [](const Employe& a, const Employe& b) { return a.salaire < b.salaire; });
    for (const auto& e : equipe) std::cout << e.resume() << '\n';
}
